mapper.select:
SELECT s.id, s.version, s.supplier_code, s.name, s.status, s.contact_name, s.contact_phone, s.address, s.remark, s.created_at, s.updated_at, s.created_by, s.updated_by FROM supplier s WHERE s.deleted = FALSE
AND (s.supplier_code ILIKE CONCAT('%', #{query.keyword}, '%') OR s.name ILIKE CONCAT('%', #{query.keyword}, '%') OR s.contact_name ILIKE CONCAT('%', #{query.keyword}, '%') OR s.contact_phone ILIKE CONCAT('%', #{query.keyword}, '%'))
AND s.status = #{query.status}

mapper.update:
UPDATE supplier
SET deleted = TRUE,
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{supplierId}
  AND version = #{version}
  AND deleted = FALSE
